questionvariables.text:
/* List of [radius,height] pairs */
dimensions:[
    [3,8],[4,10],[5,12],[6,15],[7,16],
    [8,20],[9,24],[10,25],[12,30],[15,36],
    [16,40],[18,45],[20,48],[24,60],[25,64]
];

/* Randomly choose one pair */
idx:rand(length(dimensions))+1;
chosen:dimensions[idx];

/* Extract radius and height */
radius:chosen[1];
height:chosen[2];

/* Use π ≈ 22/7 */
pi_value:22/7;

/* Surface areas */
Cylinder_curved_area:2*pi_value*radius*height;
Hemisphere_curved_area:2*pi_value*radius^2;
Cylinder_base_area:pi_value*radius^2;

/* Correct answer */
Total_surface_area:
round(
    Cylinder_curved_area
    + Hemisphere_curved_area
    + Cylinder_base_area
);

ta:Total_surface_area;

/* Common misconceptions */

/* Using full sphere surface area */
Sphere_mistake:
round(
    Cylinder_curved_area
    + 4*pi_value*radius^2
    + Cylinder_base_area
);

/* Omitting the cylinder base */
No_base_mistake:
round(
    Cylinder_curved_area
    + Hemisphere_curved_area
);

/* Adding two circular bases */
Two_bases_mistake:
round(
    Cylinder_curved_area
    + Hemisphere_curved_area
    + 2*Cylinder_base_area
);
